import{j as e,D as t}from"./Layout-QgB2NtSN.js";import{L as a}from"./LegalPage-DU-40VdG.js";const n=[{href:"/",label:"Home",minor:!0},{href:"/terms",label:"Terms",minor:!0},{href:"https://app.getnera.in/login",label:"Login"},{href:"/#contact",label:"Request a demo",cta:!0}],s=e.jsx("a",{href:"mailto:support@getnera.in",children:"support@getnera.in"}),i=[{id:"who-we-are",title:"1. Who we are",body:e.jsx("p",{children:'Getnera ("Getnera", "we", "us") is a software product operated by Afra Ventures Private Limited, CIN U62011PY2026PTC009819, 78, Lenin Street, Kosapalayam, Saram, Puducherry 605013, India. This policy explains how we handle personal data when businesses use Getnera and when people message those businesses through Getnera.'})},{id:"our-role",title:"2. Our role",body:e.jsx("p",{children:"For data about our customers' own accounts (the business and its team members), we decide how that data is used. For the messages and contact details of a business's customers, the business decides how that data is used and we process it on the business's behalf and on its instructions."})},{id:"what-we-collect",title:"3. What we collect",body:e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Account data:"})," name, business name, email, phone number and login details of the people who use Getnera."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"WhatsApp data:"})," when a business connects its WhatsApp Business account, we receive and store messages, media, phone numbers, profile names, message status (sent, delivered, read) and template details through the WhatsApp Business Platform operated by Meta."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Lead and contact data:"})," details a business records about its customers in Getnera, such as names, phone numbers, notes and lead status."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Usage data:"})," logs, device and browser information, and IP addresses, used to run and secure the service."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Billing data:"})," invoices and payment records. Card details are handled by our payment provider and are not stored by us."]})]})},{id:"how-we-use-it",title:"4. How we use it",body:e.jsxs(e.Fragment,{children:[e.jsxs("ul",{children:[e.jsx("li",{children:"To provide Getnera: show conversations, send and receive WhatsApp messages, manage leads and send approved message templates."}),e.jsx("li",{children:"To generate suggested or automated replies when the business has turned on AI features."}),e.jsx("li",{children:"To keep the service secure, prevent abuse and fix problems."}),e.jsx("li",{children:"To bill for the service and meet legal, tax and accounting obligations."}),e.jsx("li",{children:"To contact account holders about their account and service changes."})]}),e.jsx("p",{children:"We do not sell personal data. We do not use the messages of a business's customers for advertising."})]})},{id:"meta-and-whatsapp",title:"5. Meta and WhatsApp",body:e.jsxs("p",{children:["Getnera uses the WhatsApp Business Platform provided by Meta Platforms, Inc. and its affiliates. Messages sent and received through Getnera pass through Meta's systems and are also subject to ",e.jsx("a",{href:"https://www.whatsapp.com/legal/business-policy",children:"WhatsApp's Business Policy"})," and ",e.jsx("a",{href:"https://www.whatsapp.com/legal/privacy-policy",children:"WhatsApp's Privacy Policy"}),". We access a business's WhatsApp account only with the permissions the business grants, and only to provide Getnera."]})},{id:"who-else-sees-it",title:"6. Who else sees it",body:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"We share data only with service providers that help us run Getnera, under contracts that limit their use of it:"}),e.jsxs("ul",{children:[e.jsx("li",{children:"Meta, to send and receive WhatsApp messages;"}),e.jsx("li",{children:"cloud hosting and database providers;"}),e.jsx("li",{children:"AI service providers, only when AI features are turned on, to generate replies;"}),e.jsx("li",{children:"payment, email and analytics providers."})]}),e.jsx("p",{children:"We may disclose data where Indian law requires it, or to protect our rights and users' safety."})]})},{id:"how-long-we-keep-it",title:"7. How long we keep it",body:e.jsx("p",{children:"We keep account and WhatsApp data while the business's account is active. After an account is closed, we delete or anonymise its data within 90 days, except billing and records we must keep under Indian tax and company law."})},{id:"data-deletion",title:"8. Data deletion",body:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["A business can delete conversations and contacts inside Getnera at any time, or ask us to delete its whole account and data by emailing ",e.jsx("a",{href:"mailto:support@getnera.in?subject=Getnera%20data%20deletion%20request",children:"support@getnera.in"}),` with the subject "Getnera data deletion request" from the account's registered email.`]}),e.jsx("p",{children:"If you messaged a business that uses Getnera and want your data deleted, contact that business first. You can also email us with your phone number and the business's name, and we will pass on your request and help the business act on it."}),e.jsx("p",{children:"We confirm deletion requests within 7 days and complete them within 30 days."}),e.jsx("p",{children:"If you connected Getnera using Facebook, you can also remove its access at any time from your Facebook settings under Business Integrations."})]})},{id:"your-rights",title:"9. Your rights",body:e.jsxs("p",{children:["Under India's Digital Personal Data Protection Act, 2023 and other applicable law, you can ask to access, correct or delete your personal data, withdraw consent, and nominate someone to act for you. Email ",s,"."]})},{id:"security",title:"10. Security",body:e.jsx("p",{children:"We protect data with encryption in transit, encrypted storage of access tokens, access controls and logging. No system is perfectly secure, and we will notify affected businesses and authorities of a breach as the law requires."})},{id:"children",title:"11. Children",body:e.jsx("p",{children:"Getnera is a business tool and is not intended for anyone under 18."})},{id:"changes",title:"12. Changes",body:e.jsx("p",{children:"We may update this policy. We will post the new version here with a new effective date, and tell account holders by email about important changes."})},{id:"contact",title:"13. Contact and grievance officer",body:e.jsxs("p",{children:["Afra Ventures Private Limited",e.jsx("br",{}),"78, Lenin Street, Kosapalayam, Saram, Puducherry 605013, India",e.jsx("br",{}),"Email: ",s,e.jsx("br",{}),"Phone: ",e.jsx("a",{href:"tel:+918015359971",children:"+91 80153 59971"})]})}];function r(){return e.jsx(a,{title:"Privacy Policy",updated:"15 October 2026",intro:"How Getnera handles personal data, WhatsApp data and deletion requests.",sections:i,links:n})}t(e.jsx(r,{}));
